  "Opportunities lists events near you. Tap When I'm free to see only the ones that fit your week, and sign up for every date of a weekly event at once.": "अवसर में आपके पास के कार्यक्रम दिखते हैं। सिर्फ़ आपके हफ़्ते में फिट होने वाले देखने के लिए जब मैं खाली हूँ दबाएँ, और साप्ताहिक कार्यक्रम की सभी तारीखों के लिए एक साथ साइन अप करें।",
  "Check in at events": "कार्यक्रमों में चेक इन करें",
  "On the day, check in with the event's QR code or kiosk PIN, and check out with the organizer's PIN. Your hours are worked out for you.": "उस दिन कार्यक्रम के QR कोड या कियोस्क पिन से चेक इन करें, और आयोजक के पिन से चेक आउट करें। आपके घंटे अपने आप गिने जाते हैं।",
  "What's new": "नया क्या है",
  "New features show up here, with a dot when there is something you haven't seen.": "नई सुविधाएँ यहाँ दिखती हैं, और कुछ नया न देखा हो तो एक बिंदु दिखता है।",
  "Run your events": "अपने कार्यक्रम चलाएँ",
  "Post events on My Tasks. On the day, use the check-in QR code, the kiosk, a check-out PIN or the paper sheet. Everyone's hours come to you to sign at once.": "मेरे कार्य में कार्यक्रम पोस्ट करें। उस दिन चेक-इन QR कोड, कियोस्क, चेक-आउट पिन या पेपर शीट इस्तेमाल करें। सबके घंटे एक साथ आपके हस्ताक्षर के लिए आते हैं।",
  "Events you joined": "आपके जुड़े कार्यक्रम",
  "Events you signed up for yourself, with check-in on the day.": "जिन कार्यक्रमों के लिए आपने खुद साइन अप किया, उस दिन चेक-इन के साथ।",
