  "Please enter your supervisor's name.": "कृपया अपने सुपरवाइज़र का नाम डालें।",
  "Please enter your supervisor's email so you can send them the signing link.": "कृपया अपने सुपरवाइज़र का ईमेल डालें ताकि आप उन्हें हस्ताक्षर लिंक भेज सकें।",
