  "Please upload a photo or scan of your signed school form.": "कृपया हस्ताक्षर किए स्कूल फ़ॉर्म की फ़ोटो या स्कैन अपलोड करें।",
  "Please upload proof — a sign-in sheet, thank-you email, or other supporting document.": "कृपया प्रमाण अपलोड करें — हाज़िरी शीट, धन्यवाद ईमेल, या कोई अन्य दस्तावेज़।",
  "Your hours are saved, but we couldn’t make the signing link — check you’re online and signed in. Your supervisor can still sign in person.": "आपके घंटे सहेज लिए गए, लेकिन हम हस्ताक्षर लिंक नहीं बना सके — जाँचें कि आप ऑनलाइन और साइन इन हैं। आपके सुपरवाइज़र अब भी व्यक्तिगत रूप से हस्ताक्षर कर सकते हैं।",
  "Could not save — your proof file might be too large. Try a smaller image.": "सहेजा नहीं जा सका — आपकी प्रमाण फ़ाइल शायद बहुत बड़ी है। छोटी तस्वीर आज़माएँ।",
