  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer} VolunTrack में अपने मेरे कार्य पेज पर इसकी समीक्षा करके हस्ताक्षर करते हैं — कोई ईमेल नहीं भेजा जाता।",
  "The task organizer": "कार्य का आयोजक",
  "Your supervisor will get an email with a link to review these hours. If they approve, they'll sign right there to confirm it — if they reject, no signature is needed. This usually takes a day or two.": "आपके सुपरवाइज़र को इन घंटों की समीक्षा के लिंक वाला ईमेल मिलेगा। मंज़ूर करने पर वे वहीं हस्ताक्षर करेंगे — अस्वीकार करने पर हस्ताक्षर की ज़रूरत नहीं। इसमें आम तौर पर एक-दो दिन लगते हैं।",
  "Supervisor signature": "सुपरवाइज़र के हस्ताक्षर",
  "Add your supervisor’s name — they’ll sign under Signatures below.": "अपने सुपरवाइज़र का नाम जोड़ें — वे नीचे हस्ताक्षर में हस्ताक्षर करेंगे।",
  "Supervisor name and email are required so this entry can be verified.": "इस प्रविष्टि के सत्यापन के लिए सुपरवाइज़र का नाम और ईमेल ज़रूरी है।",
  "Add a supervisor to have this entry verified — optional at your school.": "इस प्रविष्टि के सत्यापन के लिए सुपरवाइज़र जोड़ें — आपके स्कूल में वैकल्पिक।",
  "Your school’s form": "आपके स्कूल का फ़ॉर्म",
  "Signatures": "हस्ताक्षर",
  "will sign this on their My Tasks page — nothing to send.": "अपने मेरे कार्य पेज पर इस पर हस्ताक्षर करेंगे — कुछ भेजना नहीं है।",
  "They’re next to me now — have them sign here instead": "वे अभी मेरे पास हैं — यहीं हस्ताक्षर करवाएँ",
