  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "नीचे दिए बटन से अपने फ़ोन के वेब ब्राउज़र (Chrome या Safari) में VolunTrack खोलें और साइन इन करें।",
  "Then use the browser’s translate, as shown below.": "फिर नीचे दिखाए अनुसार ब्राउज़र का अनुवाद इस्तेमाल करें।",
  "Use VolunTrack in another language": "VolunTrack को दूसरी भाषा में इस्तेमाल करें",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "VolunTrack अंग्रेज़ी, स्पेनिश, वियतनामी और चीनी में है, और इसकी मुख्य स्क्रीन हिंदी, अरबी, पुर्तगाली, फ़्रेंच, बांग्ला, रूसी और जापानी में भी हैं। किसी और भाषा के लिए आपका ब्राउज़र पेज का अनुवाद कर सकता है। यह मुफ़्त है और 100 से ज़्यादा भाषाओं में काम करता है, जैसे टागालोग, कोरियाई, हैतियाई क्रियोल, जर्मन और उर्दू।",
  "computer": "कंप्यूटर",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "पेज पर कहीं भी राइट-क्लिक करें, अनुवाद करें… चुनें, फिर अपनी भाषा चुनें।",
  "Android phone": "Android फ़ोन",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "⋮ (ऊपर दाईं ओर) दबाएँ, फिर अनुवाद करें…, फिर अपनी भाषा चुनें।",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "पेज मेनू (aA या एड्रेस बार के बाईं ओर का आइकन) दबाएँ, फिर अनुवाद करें….",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "एड्रेस बार में अनुवाद आइकन पर क्लिक करें, या व्यू → अनुवाद चुनें।",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "ब्राउज़र का अनुवाद आपका ब्राउज़र करता है, VolunTrack नहीं, और यह पूरी तरह सही न भी हो। ईमेल अब भी अंग्रेज़ी या आपकी चुनी VolunTrack भाषा में आते हैं।",
  "Open in browser": "ब्राउज़र में खोलें",
  "Got it": "समझ गया",
  "Default": "डिफ़ॉल्ट",
