  "Accessibility": "सुगम्यता",
  "Make VolunTrack easier to read. These settings are saved on this device only.": "VolunTrack को पढ़ने में आसान बनाएँ। ये सेटिंग्स सिर्फ़ इसी डिवाइस पर सहेजी जाती हैं।",
  "Brighter text, stronger borders and focus outlines, and underlined links.": "ज़्यादा चमकीला टेक्स्ट, मज़बूत किनारे और फ़ोकस रेखाएँ, और रेखांकित लिंक।",
  "A font that keeps similar letters like I, l and 1 easy to tell apart. Can help with dyslexia or low vision.": "ऐसा फ़ॉन्ट जिसमें I, l और 1 जैसे मिलते-जुलते अक्षर अलग पहचाने जाते हैं। डिस्लेक्सिया या कम दृष्टि में मदद कर सकता है।",
