  "Don't see it? Check the Spam folder and Promotions/Updates tab.": "नहीं दिख रहा? स्पैम फ़ोल्डर और प्रमोशन/अपडेट टैब देखें।",
  "This deployment is a static site, so there’s no email server reachable from here. The password recovery code is shown below — only you can see this screen.": "यह डिप्लॉयमेंट एक स्टैटिक साइट है, इसलिए यहाँ से कोई ईमेल सर्वर नहीं पहुँचता। पासवर्ड रिकवरी कोड नीचे दिखाया गया है — यह स्क्रीन सिर्फ़ आप देख सकते हैं।",
  "Email delivery is not available right now": "ईमेल भेजना अभी उपलब्ध नहीं है",
