  "Log your volunteer hours and send them to {school} for approval. Free for students.": "अपने स्वयंसेवा घंटे दर्ज करें और मंज़ूरी के लिए {school} को भेजें। छात्रों के लिए मुफ़्त।",
  "Create my free account": "मेरा मुफ़्त खाता बनाएँ",
  "I already have an account": "मेरा पहले से खाता है",
  "School code: {code}": "स्कूल कोड: {code}",
  "Only student accounts join a school. You are signed in with a different kind of account.": "सिर्फ़ छात्र खाते किसी स्कूल से जुड़ते हैं। आप किसी दूसरे प्रकार के खाते से साइन इन हैं।",
  "You're in {school}": "आप {school} में हैं",
