  "Free for one club or class, up to 50 students, with every school feature. No code needed.": "एक क्लब या कक्षा के लिए मुफ़्त, 50 छात्रों तक, स्कूल की हर सुविधा के साथ। कोई कोड नहीं चाहिए।",
  "Create a school account to review student hours, using the registration code we sent you.": "हमारे भेजे पंजीकरण कोड से छात्रों के घंटे जाँचने के लिए स्कूल खाता बनाएँ।",
