  "References": "सिफ़ारिशें",
  "Ask a supervisor or organizer who saw you volunteer to write a few lines about it, for college and scholarship applications. They get an email link and don’t need an account.": "किसी ऐसे सुपरवाइज़र या आयोजक से, जिसने आपको स्वयंसेवा करते देखा है, कॉलेज और स्कॉलरशिप आवेदनों के लिए इसके बारे में कुछ पंक्तियाँ लिखने को कहें। उन्हें एक ईमेल लिंक मिलेगा और खाते की ज़रूरत नहीं है।",
