  "They sign with a finger and tap Done. The signature shows up here by itself. The code works once, for 15 minutes.": "वे उंगली से हस्ताक्षर करके Done दबाते हैं। हस्ताक्षर अपने आप यहाँ दिख जाता है। कोड एक बार, 15 मिनट के लिए काम करता है।",
