  "New opportunities": "नए अवसर",
  "Email me new opportunities in these causes": "इन उद्देश्यों में नए अवसर मुझे ईमेल करें",
  "Once a week, only when something new is posted. You can stop any time.": "हफ़्ते में एक बार, सिर्फ़ तब जब कुछ नया पोस्ट हो। आप कभी भी बंद कर सकते हैं।",
  "Pick at least one cause first.": "पहले कम से कम एक उद्देश्य चुनें।",
