  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal, and remind you when your school's hours are due soon.": "चालू। जिस महीने आपने घंटे दर्ज किए, उसके बाद हम 1 तारीख को आपको ईमेल करेंगे कि आपने क्या दर्ज किया और आप अपने लक्ष्य से कितने पास हैं, और जब आपके स्कूल के घंटे जमा करने की तारीख पास होगी तो याद दिलाएँगे।",
