  "Reading… {n}%": "पढ़ा जा रहा है… {n}%",
  "Read on your phone: printed sheets work best; check handwritten ones closely.": "अपने फ़ोन पर पढ़ा गया: छपी शीट सबसे अच्छी चलती हैं; हाथ से लिखी शीट ध्यान से जाँचें।",
