  "Turned off for VolunTrack in your phone’s settings. Turn them on there to get reminders when the app is closed.": "आपके फ़ोन की सेटिंग्स में VolunTrack के लिए बंद है। ऐप बंद होने पर रिमाइंडर पाने के लिए उन्हें वहाँ चालू करें।",
  "Notifications aren’t available on this device. Reminders still show while the app is open.": "इस डिवाइस पर सूचनाएँ उपलब्ध नहीं हैं। ऐप खुला होने पर रिमाइंडर फिर भी दिखते हैं।",
