  "Scan again": "फिर से स्कैन करें",
  "No camera found. Scan the code with your phone's camera app instead.": "कोई कैमरा नहीं मिला। इसके बजाय अपने फ़ोन के कैमरा ऐप से कोड स्कैन करें।",
  "That isn't a VolunTrack check-in code.": "यह VolunTrack का चेक-इन कोड नहीं है।",
  "Camera unavailable. Allow camera access, or scan the code with your phone's camera app.": "कैमरा उपलब्ध नहीं है। कैमरा की अनुमति दें, या अपने फ़ोन के कैमरा ऐप से कोड स्कैन करें।",
  "Point your camera at the QR code on the organizer's screen: once when you arrive, and again when you leave.": "अपना कैमरा आयोजक की स्क्रीन पर दिए QR कोड की ओर करें: एक बार पहुँचने पर, और फिर जाते समय।",
  "Checking you in…": "आपको चेक इन किया जा रहा है…",
