  "You're checked in": "आप चेक इन हो गए",
  "since {time}": "{time} से",
  "Scan the same QR code again when you leave, and your hours will be logged and approved.": "जाते समय यही QR कोड फिर से स्कैन करें, और आपके घंटे दर्ज और मंज़ूर हो जाएँगे।",
  "Already checked out": "पहले ही चेक आउट हो चुका है",
  "Checked out — thank you!": "चेक आउट हो गया — धन्यवाद!",
  "1 hour was already logged for today.": "आज के लिए 1 घंटा पहले ही दर्ज हो चुका है।",
