  "1 hour logged and approved.": "1 घंटा दर्ज और मंज़ूर हुआ।",
  "{n} hours logged and approved.": "{n} घंटे दर्ज और मंज़ूर हुए।",
  "Invite friends": "दोस्तों को बुलाएँ",
  "You can invite up to {n} friends at a time.": "आप एक बार में {n} दोस्तों तक को बुला सकते हैं।",
  "Invited {n}.": "{n} को बुलाया।",
  "You can invite {n} more.": "आप {n} और को बुला सकते हैं।",
  "That's the most for this task.": "इस कार्य के लिए इतने ही हो सकते हैं।",
  "Friends' email addresses, separated by commas (up to {n})": "दोस्तों के ईमेल पते, कॉमा से अलग करके ({n} तक)",
  "friend@example.com, another@example.com": "friend@example.com, another@example.com",
  "We email each friend once with a link to this task, and don't keep their address.": "हम हर दोस्त को इस कार्य के लिंक के साथ एक बार ईमेल करते हैं, और उनका पता नहीं रखते।",
  "Send": "भेजें",
  "Calendar feed": "कैलेंडर फ़ीड",
  "Subscribe once and the tasks you signed up for or posted show up in your phone or computer calendar, and stay up to date.": "एक बार सब्सक्राइब करें और जिन कार्यों के लिए आपने साइन अप किया या जो पोस्ट किए, वे आपके फ़ोन या कंप्यूटर के कैलेंडर में दिखेंगे और अपडेट रहेंगे।",
  "Get my calendar link": "मेरा कैलेंडर लिंक पाएँ",
  "Getting your link…": "आपका लिंक लाया जा रहा है…",
  "Could not get your calendar link.": "आपका कैलेंडर लिंक नहीं मिल सका।",
  "Could not copy. Select the link and copy it yourself.": "कॉपी नहीं हो सका। लिंक चुनकर खुद कॉपी करें।",
  "Calendar feed link": "कैलेंडर फ़ीड लिंक",
  "Copied": "कॉपी हो गया",
  "Description": "विवरण",
  "Copy link": "लिंक कॉपी करें",
  "Subscribe in Apple Calendar": "Apple Calendar में सब्सक्राइब करें",
  "Subscribe in Google Calendar": "Google Calendar में सब्सक्राइब करें",
  "Anyone with this link can see your task list. If you shared it by mistake, reset it.": "इस लिंक वाला कोई भी आपकी कार्य सूची देख सकता है। अगर आपने गलती से साझा किया है, तो इसे रीसेट करें।",
  "Reset the link? The old one stops working, so calendars subscribed to it stop updating.": "लिंक रीसेट करें? पुराना काम करना बंद कर देगा, इसलिए उससे सब्सक्राइब किए कैलेंडर अपडेट होना बंद हो जाएँगे।",
  "Yes, reset": "हाँ, रीसेट करें",
  "Resetting…": "रीसेट हो रहा है…",
  "No": "नहीं",
  "Reset link": "लिंक रीसेट करें",
  "Stars": "स्टार",
  "1 star": "1 स्टार",
  "{n} stars": "{n} स्टार",
