  "No approved hours yet for this period. Yours could be first!": "इस अवधि के लिए अभी कोई मंज़ूर घंटे नहीं। आपके पहले हो सकते हैं!",
  "Nobody is on the leaderboard yet. Join and be the first!": "अभी लीडरबोर्ड पर कोई नहीं है। जुड़ें और पहले बनें!",
  "You're #{rank} with {hours} approved hours.": "आप {hours} मंज़ूर घंटों के साथ #{rank} पर हैं।",
  "You're on the leaderboard. Classmates see your first name, last initial and approved hours.": "आप लीडरबोर्ड पर हैं। सहपाठी आपका पहला नाम, उपनाम का पहला अक्षर और मंज़ूर घंटे देखते हैं।",
  "Join to appear here. Only students at your school see it: your first name, last initial and approved hours.": "यहाँ दिखने के लिए जुड़ें। इसे सिर्फ़ आपके स्कूल के छात्र देखते हैं: आपका पहला नाम, उपनाम का पहला अक्षर और मंज़ूर घंटे।",
  "Join the leaderboard": "लीडरबोर्ड से जुड़ें",
  "Monthly progress email": "मासिक प्रगति ईमेल",
  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal.": "चालू। जिस महीने आपने घंटे दर्ज किए, उसके बाद हम 1 तारीख को आपको ईमेल करेंगे कि आपने क्या दर्ज किया और आप अपने लक्ष्य से कितने पास हैं।",
  "Off. We won't email you a monthly summary of your hours.": "बंद। हम आपको आपके घंटों का मासिक सारांश ईमेल नहीं करेंगे।",
  "{name} invited you to VolunTrack": "{name} ने आपको VolunTrack पर बुलाया है",
  "You're invited to VolunTrack": "आपको VolunTrack पर बुलाया गया है",
  "Track your volunteer hours free: log hours in a minute, see your goal, and download a report when it is due.": "अपने स्वयंसेवा घंटे मुफ़्त में ट्रैक करें: एक मिनट में घंटे दर्ज करें, अपना लक्ष्य देखें, और जमा करने का समय आने पर रिपोर्ट डाउनलोड करें।",
  "Log hours in under a minute, from your phone.": "अपने फ़ोन से एक मिनट से कम में घंटे दर्ज करें।",
  "See how close you are to your goal.": "देखें कि आप अपने लक्ष्य से कितने पास हैं।",
  "Download a report when your hours are due.": "घंटे जमा करने का समय आने पर रिपोर्ट डाउनलोड करें।",
  "The free way for students to track volunteer hours.": "छात्रों के लिए स्वयंसेवा घंटे ट्रैक करने का मुफ़्त तरीका।",
  "You already have an account.": "आपका पहले से एक खाता है।",
  "I track my volunteer hours on VolunTrack. It is free. Join me:": "मैं अपने स्वयंसेवा घंटे VolunTrack पर ट्रैक करता/करती हूँ। यह मुफ़्त है। मेरे साथ जुड़ें:",
  "Earn the Bring a Friend badge when a friend joins with your link.": "जब कोई दोस्त आपके लिंक से जुड़े तो दोस्त लाओ बैज कमाएँ।",
  "{n} of 5 friends joined. Reach 5 for the Team Builder badge.": "5 में से {n} दोस्त जुड़े। टीम बिल्डर बैज के लिए 5 तक पहुँचें।",
  "{n} friends joined. Thank you for spreading the word!": "{n} दोस्त जुड़े। बात फैलाने के लिए धन्यवाद!",
  "Volunteering is better together. Send friends your link so they can track their hours too.": "स्वयंसेवा साथ में बेहतर है। दोस्तों को अपना लिंक भेजें ताकि वे भी अपने घंटे ट्रैक कर सकें।",
