  "Generate a 5-digit PIN to sync your account with the mobile app. Enter it on your phone within 15 minutes — it works once.": "अपने खाते को मोबाइल ऐप से सिंक करने के लिए 5 अंकों का पिन बनाएँ। इसे 15 मिनट के अंदर अपने फ़ोन पर डालें — यह एक बार काम करता है।",
