  "Payment Required": "भुगतान ज़रूरी है",
  "Payment required": "भुगतान ज़रूरी है",
  "Your school's account is locked until payment is verified": "भुगतान सत्यापित होने तक आपके स्कूल का खाता लॉक है",
  "Confirmation submitted": "पुष्टि जमा हुई",
  "Confirmation rejected": "पुष्टि अस्वीकार हुई",
  "We received your bank confirmation number. Please allow 3–5 business days for our team to verify it — you'll get an approval email once it's confirmed, and student uploads and management will unlock automatically.": "हमें आपका बैंक पुष्टि नंबर मिल गया। हमारी टीम को इसे सत्यापित करने के लिए कृपया 3–5 कामकाजी दिन दें — पुष्टि होते ही आपको मंज़ूरी का ईमेल मिलेगा, और छात्रों के अपलोड और प्रबंधन अपने आप खुल जाएँगे।",
  "Your confirmation could not be verified.": "आपकी पुष्टि सत्यापित नहीं हो सकी।",
  "Please double-check the number and resubmit.": "कृपया नंबर दोबारा जाँचें और फिर से जमा करें।",
  "Please complete payment using the details below, then enter the bank confirmation number.": "कृपया नीचे दी गई जानकारी से भुगतान पूरा करें, फिर बैंक पुष्टि नंबर डालें।",
