  "Upload verification PDF": "सत्यापन PDF अपलोड करें",
  "Your school hasn't completed payment yet — submissions are paused until payment is verified.": "आपके स्कूल ने अभी भुगतान पूरा नहीं किया है — भुगतान सत्यापित होने तक जमा करना रुका हुआ है।",
  "Upload volunteer hour verification documents for your school to review.": "अपने स्कूल की समीक्षा के लिए स्वयंसेवा घंटों के सत्यापन दस्तावेज़ अपलोड करें।",
  "Uploading…": "अपलोड हो रहा है…",
  "Choose PDF": "PDF चुनें",
  "Students enter this in Settings → Join school to link themselves to you, or use the join link in the starter kit below.": "छात्र खुद को आपसे जोड़ने के लिए इसे सेटिंग्स → स्कूल से जुड़ें में डालते हैं, या नीचे स्टार्टर किट का जुड़ने वाला लिंक इस्तेमाल करते हैं।",
  "Transfer requests ({n})": "ट्रांसफ़र अनुरोध ({n})",
  "These students asked to move to your school. Their volunteer record moves with them.": "इन छात्रों ने आपके स्कूल में आने का अनुरोध किया है। उनका स्वयंसेवा रिकॉर्ड उनके साथ आता है।",
