  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "एक hex मान। आपके साइन-इन पेज पर एक्सेंट के लिए इस्तेमाल होता है — टेक्स्ट या बटन के बैकग्राउंड के लिए नहीं, ताकि कोई भी रंग पढ़ने लायक रहे। VolunTrack हरे के लिए खाली छोड़ें।",
