  "Preview": "प्रीव्यू",
  "Save branding": "ब्रांडिंग सहेजें",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "यह ब्रांडिंग आपके संगठन के अपने होस्टनेम पर लागू होती है। हर स्कूल अपनी ब्रांडिंग अलग से करता है।",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "सिर्फ़ आपके स्कूल का साइन-इन पेज बदलता है। मुख्य साइट पर VolunTrack का नाम और लोगो ही रहता है।",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "ब्रांडिंग सिर्फ़ आपके अपने होस्टनेम पर दिखती है। आपके पास अभी कोई चालू डोमेन नहीं है — पहले कस्टम डोमेन में एक सेट करें, फिर यहाँ जो भी सहेजेंगे वह उसके साइन-इन पेज पर दिखेगा।",
  "Shown at sign-in on": "यहाँ साइन-इन पर दिखता है:",
  "Set how many hours your students need (one total, or per grade) to see who is behind.": "कौन पीछे है यह देखने के लिए सेट करें कि आपके छात्रों को कितने घंटे चाहिए (एक कुल, या हर कक्षा के लिए)।",
  "Allow pop-ups for this site to print the certificates.": "सर्टिफ़िकेट प्रिंट करने के लिए इस साइट के पॉप-अप चालू करें।",
  "Print certificates ({n})": "सर्टिफ़िकेट प्रिंट करें ({n})",
