  "Email {n} students how many hours they have left?": "{n} छात्रों को ईमेल करें कि उनके कितने घंटे बाकी हैं?",
  "Say why, so the student can fix it.": "कारण बताएँ, ताकि छात्र इसे ठीक कर सके।",
  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "वे प्रविष्टियाँ जिनकी किसी सुपरवाइज़र या कार्यक्रम आयोजक ने पुष्टि नहीं की। अभी ये गिनी जाती हैं; इन्हें मंज़ूर करें, या कारण के साथ वापस भेजें और छात्र के ठीक करने तक यह गिनी नहीं जाएगी।",
