  "This range hit the {n}-row limit, so the export is incomplete. Narrow the dates and run it again.": "यह अवधि {n} पंक्तियों की सीमा तक पहुँच गई, इसलिए एक्सपोर्ट अधूरा है। तारीखें कम करें और फिर से चलाएँ।",
  "Showing 25 of {n}. The exports contain every student.": "{n} में से 25 दिखाए जा रहे हैं। एक्सपोर्ट में हर छात्र है।",
  "Loading domains…": "डोमेन लोड हो रहे हैं…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "कस्टम डोमेन पर दावा किया जा सकता है और उनका स्वामित्व सत्यापित किया जा सकता है, पर यह सर्वर अभी सर्टिफ़िकेट जारी नहीं कर सकता, इसलिए डोमेन चालू नहीं हो सकता। VolunTrack सहायता से संपर्क करें।",
