  "Skip to content": "सामग्री पर जाएँ",
  "Weekly adviser email": "सलाहकार के लिए साप्ताहिक ईमेल",
  "On. Every Monday we email you what needs your review, who is behind on hours and what students logged that week.": "चालू। हर सोमवार हम आपको ईमेल करते हैं कि आपकी समीक्षा के लिए क्या है, कौन घंटों में पीछे है और छात्रों ने उस हफ़्ते क्या दर्ज किया।",
  "Off. We won't email you a weekly summary.": "बंद। हम आपको साप्ताहिक सारांश ईमेल नहीं करेंगे।",
