  "Great helping!": "बहुत बढ़िया मदद!",
  "You helped for {n} hours.": "आपने {n} घंटे मदद की।",
  "{filled} of {stars} stars": "{stars} में से {filled} स्टार",
  "Each star is {n} hours of helping.": "हर स्टार {n} घंटे की मदद है।",
  "Your card is full! Keep helping if you want to.": "आपका कार्ड भर गया! चाहें तो मदद करते रहें।",
  "{n} more hours to fill your card.": "आपका कार्ड भरने के लिए {n} घंटे और।",
  "Kids your age have a small goal. Every little bit helps!": "आपकी उम्र के बच्चों का छोटा लक्ष्य होता है। हर छोटी मदद मायने रखती है!",
  "New main admin": "नए मुख्य एडमिन",
  "A parent must come with volunteers in 5th grade or younger": "5वीं कक्षा या उससे छोटे स्वयंसेवकों के साथ एक अभिभावक को आना होगा",
  "K–5th grade: parent comes too": "KG–5वीं कक्षा: अभिभावक भी साथ आएँ",
  "They’ll tell you which parent or guardian is coming when they sign up.": "साइन अप करते समय वे बताएँगे कि कौन से अभिभावक साथ आ रहे हैं।",
  "1 entry is saved on this device and waiting to send.": "1 प्रविष्टि इस डिवाइस पर सहेजी है और भेजे जाने का इंतज़ार कर रही है।",
  "{n} entries are saved on this device and waiting to send.": "{n} प्रविष्टियाँ इस डिवाइस पर सहेजी हैं और भेजे जाने का इंतज़ार कर रही हैं।",
  "Couldn’t reach VolunTrack yet. It keeps trying by itself.": "अभी VolunTrack तक नहीं पहुँच सके। यह खुद कोशिश करता रहेगा।",
  "They send by themselves when you’re back online.": "ऑनलाइन वापस आने पर ये अपने आप भेज दी जाएँगी।",
  "Send now": "अभी भेजें",
  "Saved on this device. It sends by itself when you’re back online.": "इस डिवाइस पर सहेजा गया। ऑनलाइन वापस आने पर यह अपने आप भेज दिया जाएगा।",
  "Waiting to send": "भेजे जाने का इंतज़ार",
  "Could not make the packet.": "पैकेट नहीं बन सका।",
  "End-of-year packet": "साल के आखिर का पैकेट",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "हर स्कूल के फ़ोल्डर के साथ एक ZIP: सारांश, हर प्रविष्टि, और हर छात्र की घंटों की रिपोर्ट।",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "एक ZIP जिसमें सारांश, हर प्रविष्टि, मंज़ूरी का इतिहास, आवश्यकता पूरी करने वाले छात्रों के सर्टिफ़िकेट, और हर छात्र की घंटों की रिपोर्ट हो।",
  "School year": "स्कूल वर्ष",
  "Making student reports… {done} of {total}": "छात्रों की रिपोर्ट बन रही हैं… {total} में से {done}",
  "Making the packet…": "पैकेट बन रहा है…",
  "Download packet": "पैकेट डाउनलोड करें",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "स्कूल वर्ष 1 अगस्त से 31 जुलाई तक चलता है। ZIP में छात्रों की निजी जानकारी है, इसलिए इसे कहीं सुरक्षित रखें।",
  "A parent or guardian must come with you to this event. Who is coming? (their name)": "इस कार्यक्रम में आपके साथ किसी अभिभावक को आना होगा। कौन आ रहा है? (उनका नाम)",
  "Parent coming: {name}": "साथ आने वाले अभिभावक: {name}",
