  "Check that a VolunTrack transcript is genuine and has not been changed since it was issued. No account needed. The file is checked by our server and not stored.": "जाँचें कि VolunTrack ट्रांसक्रिप्ट असली है और जारी होने के बाद बदली नहीं गई। खाते की ज़रूरत नहीं। फ़ाइल हमारा सर्वर जाँचता है और रखता नहीं।",
